// ============================================================================
// Decorative background: a slowly scrolling collage of batch / class photos + optional background music.
//
//  * Purely decorative. It only touches: its own fixed layer (#bgLayer), the music button (#musicBtn) and a class on <html>.
//    It never reads or writes the app's state, search, filters, cart or files, and any failure leaves the app untouched.
//  * Photos and music are listed by a small static file (photos.json, generated by tools/build-gallery-manifest.mjs — no API call at all);
//    if it is missing, they are DISCOVERED from the public GitHub repository tree instead (one request, cached).
//    The image / audio files themselves always come straight from GitHub, never from the app's own server.
//  * Setup and options: ./README.md      Settings: ./gallery-config.json
//
// Vanilla JS, no dependencies. Everything environment-specific (fetch, storage, document, Audio, clock, random) can be injected,
// which is how it is tested.
// ============================================================================

export const IMAGE_EXT = ["jpg", "jpeg", "png", "webp", "avif", "gif"];
export const AUDIO_EXT = ["mp3", "m4a", "aac", "ogg", "opus", "wav", "webm"];

export const DEFAULT_CONFIG = Object.freeze({
  enabled: true,
  owner: "", repo: "", branch: "main",
  projectPath: "",                                   // folder of the project INSIDE the repo ("" = repo root)
  photosFolder: "public/app/background/photos",      // relative to projectPath
  musicFolder: "public/app/background/music",
  manifest: "photos.json",                           // static list next to gallery.js ("" = skip it and always ask GitHub)
  cacheTtlMinutes: 5,
  mediaHost: "raw",                                  // "raw" = raw.githubusercontent.com, "jsdelivr" = cdn.jsdelivr.net
  scrollDurationSeconds: 40,                         // seconds a column needs to move by ONE screen height (bigger = slower)
  maxPhotos: 3000,
  maxImageBytes: 1500000,
  tileAspect: 0.75,                                  // width / height of every tile (0.75 = portrait 3:4). Photos are shown whole, never cropped
  backgroundOpacity: 0.91,                           // opacity of the background COLOUR over the photos: 1 = plain colour, no photos; lower = photos show more (0.4 … 0.97)
  cardOpacity: 1,                                    // how solid the app's cards / buttons / header are (1 = exactly as before, lower = glassy)
  tintOpacity: 0,                                    // optional Royal Blue (#1D4ED8) veil, 0 = none
  musicFile: "",
  musicVolume: 0.18,
  maxAudioBytes: 25000000,
  autoplayMusic: true,
  startMusicOnFirstTap: true
});

const num = (v, d, lo, hi) => { const n = Number(v); return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d; };
const str = (v, d = "") => (typeof v === "string" ? v.trim() : d);
const cleanPath = (p) => str(p).replace(/\\/g, "/").split("/").filter((x) => x && x !== "." && x !== "..").join("/");

// backgroundOpacity is the setting. (ghostOpacity = how visible the photos are = 1 - backgroundOpacity; still understood if an older config has it.)
const bgOpacity = (r) => num(r.backgroundOpacity !== undefined ? r.backgroundOpacity : r.ghostOpacity !== undefined ? 1 - Number(r.ghostOpacity) : undefined, DEFAULT_CONFIG.backgroundOpacity, 0.4, 0.97);

export function normalizeConfig(raw) {
  const r = raw && typeof raw === "object" ? raw : {};
  const d = DEFAULT_CONFIG;
  return {
    enabled: r.enabled !== false,
    owner: str(r.owner), repo: str(r.repo), branch: str(r.branch, d.branch) || d.branch,
    projectPath: cleanPath(r.projectPath),
    photosFolder: cleanPath(r.photosFolder) || d.photosFolder,
    musicFolder: cleanPath(r.musicFolder) || d.musicFolder,
    manifest: r.manifest === undefined ? d.manifest : cleanPath(r.manifest),
    cacheTtlMinutes: num(r.cacheTtlMinutes, d.cacheTtlMinutes, 0, 24 * 60),
    mediaHost: r.mediaHost === "jsdelivr" ? "jsdelivr" : "raw",
    scrollDurationSeconds: num(r.scrollDurationSeconds, d.scrollDurationSeconds, 5, 3600),
    maxPhotos: Math.floor(num(r.maxPhotos, d.maxPhotos, 1, 20000)),
    maxImageBytes: num(r.maxImageBytes, d.maxImageBytes, 10000, 50e6),
    tileAspect: num(r.tileAspect, d.tileAspect, 0.3, 3),
    backgroundOpacity: bgOpacity(r),
    cardOpacity: num(r.cardOpacity, d.cardOpacity, 0.15, 1),
    tintOpacity: num(r.tintOpacity, d.tintOpacity, 0, 0.9),
    musicFile: str(r.musicFile),
    musicVolume: num(r.musicVolume, d.musicVolume, 0, 1),
    maxAudioBytes: num(r.maxAudioBytes, d.maxAudioBytes, 10000, 200e6),
    autoplayMusic: r.autoplayMusic !== false,
    startMusicOnFirstTap: r.startMusicOnFirstTap !== false
  };
}

// owner / repo are GitHub names: nothing else is allowed into a URL. Path segments are percent-encoded one by one.
const NAME_RE = /^[A-Za-z0-9_.-]{1,100}$/;
export const isConfigured = (c) => !!(c && c.owner && c.repo && NAME_RE.test(c.owner) && NAME_RE.test(c.repo) && c.branch);
const encPath = (p) => String(p).split("/").map(encodeURIComponent).join("/");

export function mediaUrl(cfg, path) {
  const branch = encPath(cfg.branch);
  return cfg.mediaHost === "jsdelivr"
    ? `https://cdn.jsdelivr.net/gh/${cfg.owner}/${cfg.repo}@${branch}/${encPath(path)}`
    : `https://raw.githubusercontent.com/${cfg.owner}/${cfg.repo}/${branch}/${encPath(path)}`;
}
export const treeUrl = (cfg) => `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/git/trees/${encodeURIComponent(cfg.branch)}?recursive=1`;
export const contentsUrl = (cfg, folder) => `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents/${encPath(folder)}?ref=${encodeURIComponent(cfg.branch)}`;

const join = (...p) => p.map(cleanPath).filter(Boolean).join("/");
const extOf = (path) => { const m = /\.([A-Za-z0-9]+)$/.exec(path); return m ? m[1].toLowerCase() : ""; };
const baseName = (path) => String(path).split("/").pop();

// ---- listing: tree entries ({ path, type, size }) -> { photos:[path], music:[path] } -------------------------------------
export function pickFromEntries(entries, cfg) {
  const photoDir = join(cfg.projectPath, cfg.photosFolder) + "/";
  const musicDir = join(cfg.projectPath, cfg.musicFolder) + "/";
  const photos = [], music = [];
  for (const e of Array.isArray(entries) ? entries : []) {
    if (!e || e.type !== "blob" || typeof e.path !== "string") continue;
    const ext = extOf(e.path), size = Number(e.size);
    if (e.path.startsWith(photoDir) && IMAGE_EXT.includes(ext)) {
      if (Number.isFinite(size) && size > cfg.maxImageBytes) continue;          // too heavy for a background: ignored
      photos.push(e.path);
    } else if (e.path.startsWith(musicDir) && AUDIO_EXT.includes(ext)) {
      if (Number.isFinite(size) && size > cfg.maxAudioBytes) continue;
      music.push(e.path);
    }
  }
  const byName = (a, b) => (a.toLowerCase() < b.toLowerCase() ? -1 : a.toLowerCase() > b.toLowerCase() ? 1 : a < b ? -1 : a > b ? 1 : 0);
  photos.sort(byName); music.sort((a, b) => byName(baseName(a), baseName(b)) || byName(a, b));
  return { photos: photos.slice(0, cfg.maxPhotos), music };
}

// ---- the static list (photos.json): { v:1, photos:["a.jpg","sub/b.webp"], music:["song.mp3"] }, paths relative to the two folders ------
export function parseManifest(json, cfg) {
  if (!json || typeof json !== "object" || Number(json.v) !== 1) return null;
  const take = (arr, exts, dir) => {
    const out = [];
    for (const rel of Array.isArray(arr) ? arr : []) {
      if (typeof rel !== "string" || !rel || rel.includes("\\") || rel.startsWith("/") || rel.split("/").some((x) => !x || x === "." || x === "..")) continue;
      if (exts.includes(extOf(rel))) out.push(join(cfg.projectPath, dir, rel));
    }
    return out;
  };
  return { photos: take(json.photos, IMAGE_EXT, cfg.photosFolder).slice(0, cfg.maxPhotos), music: take(json.music, AUDIO_EXT, cfg.musicFolder) };
}
export async function loadManifest(cfgIn, env = {}) {
  const cfg = normalizeConfig(cfgIn);
  const fetchFn = env.fetch || (typeof fetch === "function" ? fetch.bind(globalThis) : null);
  if (!cfg.manifest || !env.base || !fetchFn) return null;
  const ctl = typeof AbortController === "function" ? new AbortController() : null;
  const timer = ctl ? setTimeout(() => ctl.abort(), env.timeoutMs || 6000) : null;
  try {
    const res = await fetchFn(new URL(cfg.manifest, env.base).href, { cache: "no-cache", signal: ctl ? ctl.signal : undefined });   // same server: a tiny static file, revalidated (304)
    if (!res || !res.ok) return null;
    const list = parseManifest(await res.json(), cfg);
    return list && (list.photos.length || list.music.length) ? list : null;
  } catch (_) { return null; } finally { if (timer) clearTimeout(timer); }
}
// manifest first (no GitHub API call, no rate limit); GitHub tree only when there is no usable manifest
export async function findMedia(cfgIn, env = {}) {
  const cfg = normalizeConfig(cfgIn);
  if (!isConfigured(cfg)) return { photos: [], music: [], source: "none" };
  const m = await loadManifest(cfg, env);
  if (m) return { ...m, source: "manifest" };
  return discover(cfg, env);
}

// ---- discovery with a short cache ------------------------------------------------------------------------------------
const sigOf = (c) => [c.owner, c.repo, c.branch, c.projectPath, c.photosFolder, c.musicFolder, c.maxPhotos, c.maxImageBytes, c.maxAudioBytes].join("|");
const CACHE_KEY = "bg:list:v1";
const inflight = new Map();

function readCache(storage, sig) {
  try { const c = JSON.parse(storage.getItem(CACHE_KEY) || "null"); return c && c.sig === sig && Array.isArray(c.photos) && Array.isArray(c.music) ? c : null; } catch (_) { return null; }
}
function writeCache(storage, sig, list, now) {
  try { storage.setItem(CACHE_KEY, JSON.stringify({ sig, at: now, photos: list.photos, music: list.music })); } catch (_) {}
}
async function getJson(fetchFn, url, timeoutMs) {
  const ctl = typeof AbortController === "function" ? new AbortController() : null;
  const timer = ctl ? setTimeout(() => ctl.abort(), timeoutMs) : null;
  try {
    const res = await fetchFn(url, { headers: { Accept: "application/vnd.github+json" }, signal: ctl ? ctl.signal : undefined });
    if (!res || !res.ok) throw new Error("github " + (res && res.status));        // 403/429 = rate limited, 404 = wrong repo/branch
    return await res.json();
  } finally { if (timer) clearTimeout(timer); }
}
async function fetchListing(cfg, fetchFn, timeoutMs) {
  const tree = await getJson(fetchFn, treeUrl(cfg), timeoutMs);
  let entries = tree && tree.tree;
  if (tree && tree.truncated) {                                                    // huge repo: ask the two folders directly
    entries = [];
    for (const folder of [join(cfg.projectPath, cfg.photosFolder), join(cfg.projectPath, cfg.musicFolder)]) {
      try {
        const items = await getJson(fetchFn, contentsUrl(cfg, folder), timeoutMs);
        for (const it of Array.isArray(items) ? items : []) if (it && it.type === "file") entries.push({ path: it.path, type: "blob", size: it.size });
      } catch (_) {}
    }
  }
  return pickFromEntries(entries, cfg);
}

// -> { photos:[path], music:[path], source: "cache"|"github"|"stale"|"none" }
export async function discover(cfgIn, env = {}) {
  const cfg = normalizeConfig(cfgIn);
  const storage = env.storage || memoryStorage();
  const fetchFn = env.fetch || (typeof fetch === "function" ? fetch.bind(globalThis) : null);
  const now = typeof env.now === "function" ? env.now() : Date.now();
  if (!isConfigured(cfg) || !fetchFn) return { photos: [], music: [], source: "none" };
  const sig = sigOf(cfg);
  const cached = readCache(storage, sig);
  if (cached && now - Number(cached.at) < cfg.cacheTtlMinutes * 60000) return { photos: cached.photos, music: cached.music, source: "cache" };
  if (inflight.has(sig)) return inflight.get(sig);                                 // one request even if asked twice at once
  const p = (async () => {
    try {
      const list = await fetchListing(cfg, fetchFn, env.timeoutMs || 8000);
      writeCache(storage, sig, list, now);
      return { ...list, source: "github" };
    } catch (_) {
      return cached ? { photos: cached.photos, music: cached.music, source: "stale" } : { photos: [], music: [], source: "none" };
    } finally { inflight.delete(sig); }
  })();
  inflight.set(sig, p);
  return p;
}
function memoryStorage() { const m = new Map(); return { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => void m.set(k, String(v)), removeItem: (k) => void m.delete(k) }; }

// ---- music choice ---------------------------------------------------------------------------------------------------
// musicFile set  -> that exact file (a file name, or a path ending with it; case-insensitive)
// empty / not found -> the first file in alphabetical order (deterministic)
export function pickMusic(paths, musicFile) {
  const list = Array.isArray(paths) ? paths : [];
  if (!list.length) return null;
  const want = str(musicFile).replace(/\\/g, "/").toLowerCase();
  if (want) {
    const hit = list.find((p) => p.toLowerCase() === want) || list.find((p) => p.toLowerCase().endsWith("/" + want)) || list.find((p) => baseName(p).toLowerCase() === want);
    if (hit) return hit;
  }
  return [...list].sort((a, b) => (baseName(a).toLowerCase() < baseName(b).toLowerCase() ? -1 : baseName(a).toLowerCase() > baseName(b).toLowerCase() ? 1 : a < b ? -1 : 1))[0];
}

// ---- layout helpers -------------------------------------------------------------------------------------------------
// Fisher–Yates, new array, fresh on every call (the order is NOT stored anywhere).
export function shuffle(arr, rnd = Math.random) {
  const a = Array.from(arr);
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
export const columnCountFor = (width) => (Number(width) >= 700 ? 4 : 3);
// round-robin: every photo lands in exactly one column, neighbours differ
export function splitColumns(list, cols) {
  const out = Array.from({ length: cols }, () => []);
  list.forEach((x, i) => out[i % cols].push(x));
  return out;
}
const GAP = 8;

// Plans one column: which items (cycled until they cover the screen), the aspect of each tile, the loop length in px.
export function planColumn(items, colW, viewH, colIndex, ar = 0.75) {
  const need = Math.max(viewH * 1.3, 200);
  const seq = []; let h = 0, k = 0;
  const src = items.length ? items : [null];
  while ((h < need || k < src.length) && k < 4000) {              // every item once at least; repeated only to fill the screen
    seq.push({ item: src[k % src.length], ar });
    h += colW / ar + GAP; k++;
  }
  return { seq, halfPx: h };
}

// Small SVG tiles shown when no repository is configured or it has no photos. Tiny data: URIs, no files.
export function demoPhotos(n = 24) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const h = (i * 47 + 205) % 360, x = 80 + ((i * 131) % 480), y = 70 + ((i * 89) % 330), r = 70 + ((i * 37) % 90);
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 480"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${h},55%,62%)"/><stop offset="1" stop-color="hsl(${(h + 40) % 360},60%,36%)"/></linearGradient></defs><rect width="640" height="480" fill="url(#g)"/><circle cx="${x}" cy="${y}" r="${r}" fill="#fff" opacity=".18"/><circle cx="${640 - x}" cy="${480 - y}" r="${Math.round(r * 0.6)}" fill="#fff" opacity=".12"/></svg>`;
    out.push("data:image/svg+xml," + encodeURIComponent(svg));
  }
  return out;
}

// ---- icons (small, inline) ------------------------------------------------------------------------------------------
const SVG = (inner) => `<svg viewBox="0 0 24 24" width="19" height="19" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
const ICON_NOTE = SVG('<path d="M9 18V5l11-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/>');
const ICON_SOUND = SVG('<path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/><path d="M19 5a10 10 0 0 1 0 14"/>');
const ICON_MUTED = SVG('<path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="m22 9-6 6"/><path d="m16 9 6 6"/>');

// ---- the background ------------------------------------------------------------------------------------------------
export async function startBackground(opts = {}) {
  const doc = opts.document || (typeof document !== "undefined" ? document : null);
  const win = opts.window || (typeof window !== "undefined" ? window : null);
  if (!doc || !win) return null;
  const storage = opts.storage || (() => { try { return win.localStorage; } catch (_) { return memoryStorage(); } })();
  const rnd = opts.random || Math.random;
  let rawCfg = opts.config;
  if (!rawCfg) {
    try {
      const f = opts.fetch || win.fetch.bind(win);
      const res = await f(new URL("gallery-config.json", opts.configBase || import.meta.url).href, { cache: "no-cache" });
      rawCfg = res && res.ok ? await res.json() : {};
    } catch (_) { rawCfg = {}; }
  }
  const cfg = normalizeConfig(rawCfg);
  try {                                                                       // preview without editing files: open the app with  ?bgopacity=0.85  (not saved)
    const q = new URLSearchParams(opts.search !== undefined ? opts.search : win.location.search).get("bgopacity");
    if (q !== null && q !== "" && Number.isFinite(Number(q))) cfg.backgroundOpacity = bgOpacity({ backgroundOpacity: Number(q) });
  } catch (_) {}
  if (!cfg.enabled) { const b = doc.getElementById("musicBtn"); if (b) b.hidden = true; return null; }

  const root = doc.documentElement;
  const ctl = { cfg, layer: null, audio: null, destroyed: false, destroy() {} };
  const cleanups = [];

  // 1. what to show
  const found = await findMedia(cfg, { fetch: opts.fetch || (win.fetch ? win.fetch.bind(win) : undefined), storage, now: opts.now, base: opts.configBase || import.meta.url });
  if (ctl.destroyed) return ctl;
  const isDemo = !found.photos.length;
  const urls = isDemo ? demoPhotos(24) : found.photos.map((p) => mediaUrl(cfg, p));
  ctl.source = isDemo ? "demo" : found.source;
  ctl.photoCount = urls.length;

  // 2. the layer
  const shuffled = shuffle(urls, rnd);
  ctl.order = shuffled;
  const layer = doc.createElement("div");
  layer.id = "bgLayer"; layer.className = "bg-layer"; layer.setAttribute("aria-hidden", "true");
  layer.style.setProperty("--bg-tint", String(cfg.tintOpacity));
  layer.style.setProperty("--bg-ghost", String(+(1 - cfg.backgroundOpacity).toFixed(3)));
  const grid = doc.createElement("div"); grid.className = "bg-grid";
  const tint = doc.createElement("div"); tint.className = "bg-tint";
  const color = doc.createElement("div"); color.className = "bg-color";            // gives the photos the app's own hue (see gallery.css)
  layer.append(grid, color, tint);
  doc.body.insertBefore(layer, doc.body.firstChild);
  ctl.layer = layer;

  let lastCols = 0, lastH = 0;
  const render = () => {
    const vw = win.innerWidth || 390, vh = win.innerHeight || 800;
    const cols = columnCountFor(vw);
    const colW = Math.max(40, (vw - GAP * (cols - 1)) / cols);
    const flip = rnd() < 0.5 ? 0 : 1;
    const pool = shuffled.length >= cols ? shuffled : Array.from({ length: cols }, (_, i) => shuffled[i % shuffled.length]);   // fewer photos than columns: reuse, never an empty column
    const columns = splitColumns(pool, cols);
    grid.textContent = "";
    grid.style.setProperty("--bg-cols", String(cols));
    const frag = doc.createDocumentFragment();
    columns.forEach((items, ci) => {
      const { seq, halfPx } = planColumn(items, colW, vh, ci, cfg.tileAspect);
      const col = doc.createElement("div"); col.className = "bg-col";
      const track = doc.createElement("div"); track.className = "bg-track";
      const mk = (s) => {
        const img = doc.createElement("img");
        img.className = "bg-tile"; img.alt = ""; img.decoding = "async"; img.loading = "lazy"; img.draggable = false;
        img.setAttribute("referrerpolicy", "no-referrer");
        img.style.aspectRatio = String(s.ar);
        img.src = s.item;
        img.addEventListener("error", () => img.classList.add("bad"));          // keeps its size, so the loop never jumps
        return img;
      };
      for (let copy = 0; copy < 2; copy++) for (const s of seq) track.appendChild(mk(s));       // content twice = seamless loop
      const speed = (vh / cfg.scrollDurationSeconds) * (0.8 + rnd() * 0.45);                      // px/s, slightly different per column
      const dur = Math.max(8, halfPx / speed);
      track.style.setProperty("--bg-dur", dur.toFixed(1) + "s");
      track.style.setProperty("--bg-delay", "-" + (rnd() * dur).toFixed(1) + "s");               // a different starting point each
      track.dataset.dir = (ci + flip) % 2 ? "down" : "up";
      col.appendChild(track); frag.appendChild(col);
    });
    grid.appendChild(frag);
    lastCols = cols; lastH = vh;
  };
  render();
  root.classList.add("has-bg");
  root.style.setProperty("--glass", Math.round(cfg.cardOpacity * 100) + "%");
  root.style.setProperty("--glass-top", Math.min(100, Math.round(cfg.cardOpacity * 100) + 15) + "%");
  const raf = win.requestAnimationFrame ? win.requestAnimationFrame.bind(win) : (f) => setTimeout(f, 16);
  raf(() => layer.classList.add("ready"));

  let rt = null;
  const onResize = () => {
    clearTimeout(rt);
    rt = setTimeout(() => { const vw = win.innerWidth || 390, vh = win.innerHeight || 800; if (columnCountFor(vw) !== lastCols || vh > lastH * 1.2) render(); }, 250);
  };
  win.addEventListener("resize", onResize);
  cleanups.push(() => { win.removeEventListener("resize", onResize); clearTimeout(rt); });

  // 3. music (optional)
  const btn = doc.getElementById("musicBtn");
  const musicPath = pickMusic(found.music, cfg.musicFile);
  if (btn && musicPath) setupMusic(ctl, { doc, win, storage, btn, url: mediaUrl(cfg, musicPath), cfg, Audio: opts.Audio || win.Audio, cleanups });
  else if (btn) btn.hidden = true;                                                             // no music uploaded: no control, no error

  ctl.destroy = () => {
    ctl.destroyed = true; cleanups.forEach((f) => { try { f(); } catch (_) {} });
    if (ctl.audio) { try { ctl.audio.pause(); } catch (_) {} }
    layer.remove(); root.classList.remove("has-bg"); root.style.removeProperty("--glass"); root.style.removeProperty("--glass-top");
  };
  return ctl;
}

function setupMusic(ctl, { doc, win, storage, btn, url, cfg, Audio: AudioCtor, cleanups }) {
  if (typeof AudioCtor !== "function") { btn.hidden = true; return; }
  let audio;
  try { audio = new AudioCtor(); } catch (_) { btn.hidden = true; return; }
  audio.loop = true; audio.preload = "none"; audio.volume = cfg.musicVolume; audio.src = url;
  ctl.audio = audio;
  const PREF = "bg:music";                                    // "off" once the user muted on purpose
  const pref = () => { try { return storage.getItem(PREF); } catch (_) { return null; } };
  const setPref = (v) => { try { v ? storage.setItem(PREF, v) : storage.removeItem(PREF); } catch (_) {} };
  const playing = () => !audio.paused && !audio.ended;
  const label = () => (!playing() ? "Play background music" : audio.muted ? "Unmute background music" : "Mute background music");
  const paint = () => {
    const l = label();
    btn.innerHTML = !playing() ? ICON_NOTE : audio.muted ? ICON_MUTED : ICON_SOUND;
    btn.setAttribute("aria-label", l); btn.title = l;
    btn.setAttribute("aria-pressed", playing() && !audio.muted ? "true" : "false");
    btn.dataset.state = !playing() ? "stopped" : audio.muted ? "muted" : "playing";
  };
  const tryPlay = async () => {
    try { const r = audio.play(); if (r && typeof r.then === "function") await r; return true; } catch (_) { return false; }   // blocked / unsupported file: never fatal
  };
  btn.hidden = false; paint();
  for (const ev of ["play", "pause", "ended", "volumechange", "error"]) audio.addEventListener(ev, paint);

  btn.addEventListener("click", async () => {
    if (!playing()) { audio.muted = false; setPref(null); await tryPlay(); }                // tap = start / resume
    else { audio.muted = !audio.muted; setPref(audio.muted ? "off" : null); }                // playing: mute / unmute
    paint();
  });

  // autoplay at a quiet volume; if the browser / Telegram blocks it, the first tap anywhere starts it
  const armFirstTap = () => {
    if (!cfg.startMusicOnFirstTap) return;
    const onTap = async (e) => {
      if (btn.contains(e.target) || playing() || pref() === "off") return;
      if (await tryPlay()) { audio.muted = false; doc.removeEventListener("click", onTap, true); doc.removeEventListener("keydown", onTap, true); paint(); }
    };
    doc.addEventListener("click", onTap, true); doc.addEventListener("keydown", onTap, true);
    cleanups.push(() => { doc.removeEventListener("click", onTap, true); doc.removeEventListener("keydown", onTap, true); });
  };
  if (cfg.autoplayMusic && pref() !== "off") {
    tryPlay().then((ok) => { if (!ok) armFirstTap(); paint(); });
  } else if (pref() !== "off") armFirstTap();

  // pause while the app is in the background, resume after (only if it was playing)
  let resume = false;
  const onVis = () => {
    if (doc.hidden) { resume = playing(); if (resume) audio.pause(); }
    else if (resume) { resume = false; tryPlay(); }
  };
  doc.addEventListener("visibilitychange", onVis);
  cleanups.push(() => doc.removeEventListener("visibilitychange", onVis));
}
